        {
          "text": "Some candidates get hired despite limited language skills",
          "evidence": [29]
        },
        {
          "text": "Higher education rarely matters for hiring decisions",
          "evidence": [32]
        },
        {
          "text": "Salary for U3's position was low, comparable to fast‑food wages",
          "evidence": [37]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language issues and learning",
      "claims": [
        {
          "text": "German is the main spoken language in Austria, but English is also used",
          "evidence": [14, 15]
        },
        {
          "text": "U3 is learning the local language to feel more comfortable in daily life",
          "evidence": [47]
        },
        {
          "text": "U1 feels insecure speaking English outside of work",
          "evidence": [51, 52]
        }
      ]
    },
    {
      "id": "salary-expectations",
      "title": "Salary expectations abroad",
      "claims": [
        {
          "text": "U3 believes salaries in Europe are generally higher than in Ukraine but are often overlooked",
          "evidence": [35]
        },
        {
          "text": "U3 received a minimal salary after stating he just needed a job",
          "evidence": [37]
        }
      ]
    },
    {
      "id": "future-plans",
      "title": "Future relocation considerations",
      "claims": [
        {
          "text": "U3 is considering moving to Warsaw for a tech event",
          "evidence": [59]
        },
        {
          "text": "U3's partner, who has lived in Austria for over 10 years, is pessimistic about the country's future",
          "evidence": [60]
        },
        {
          "text": "U3 still views Austria as the best choice among European countries",
          "evidence": [60]
        }
      ]
    }
